    if res.hour is not None:
        if res.hour == 24:
            # ISO 8601 allows 24:00 to represent midnight
            if res.minute is not None and res.minute != 0:
                return False
            if res.second is not None and res.second != 0:
                return False
            if res.microsecond is not None and res.microsecond != 0:
                return False
        elif not (0 <= res.hour <= 23):
            return False

    if res.minute is not None and not (0 <= res.minute <= 59):
        return False

    if res.second is not None and not (0 <= res.second <= 59):
        return False

    if res.microsecond is not None and not (0 <= res.microsecond <= 999999):
        return False

    if res.month is not None and not (1 <= res.month <= 12):
        return False

    if res.day is not None and not (1 <= res.day <= 31):
        return False

    return True

