        except ValueError:
            raise ValueError("Invalid second value")
        if not (0 <= s_s < 60):
            raise ValueError("second must be in 0..60")
        ret['second'] = int(s_s)
        ret['microsecond'] = int((s_s % 1) * 1e6)

